    "top100_scene1_desc": "Kuçe, qada bajêr, dibistan, dikan û niştecihên bajêr keşf bikin. Bêjeyên gelek caran tên bikaranîn ên wekî <em>mand (mêr), kvinde (jin), bil (erebe), vej (kuçe/rê), skole (dibistan), tid (dem), penge (pere), læge (bijîşk)</em> û <em>tur (ger)</em> fêr bibin.",
