    "top100_scene2_title": "🍳 Mal û mitbax",
    "top100_scene2_desc": "Xwarinên malbatê, xwarin, mobîlya û cil û bergên li malê keşf bikin. Bêjeyên wekî <em>mor (dayik), far (bav), barn (zarok), bord (mêze), stol (kursî), kop (fîncan), kaffe (qehwe), mad (xwarin), seng (nivîn), hund (se)</em> û <em>problem (pirsgirêk)</em> fêr bibin.",
    "top100_scene2_btn": "Herin mitbaxê ➔",
