    "top100_scene3_title": "🏫 Pola dersê û nivîsgeh",
    "top100_scene3_desc": "Hîndekarî, ziman, pirtûk, kompûter û xebata nivîsgehê keşf bikin. Bêjeyên wekî <em>lærer (mamoste), elev (xwendekar), bog (pirtûk), computer (kompûter), papir (kaxez), opgave (peywir), spørgsmål (pirs), svar (bersiv), møde (civîn)</em> û <em>arbejde (kar)</em> fêr bibin.",
    "top100_scene3_btn": "Herin polê ➔",
    "top100_scene4_title": "🌲 Xweza û dema vala",
    "top100_scene4_desc": "Daristan, perav, hewa, laş û çalakiyên dema vala keşf bikin. Bêjeyên wekî <em>skov (daristan), strand (perav), vejr (hewa), fugl (çivîk), blomst (kulîlk), hånd (dest), hoved (serî), fod (pê), musik (muzîk), film (fîlm), spil (lîstik)</em> û <em>ferie (bêhnvedan)</em> fêr bibin.",
