    "top100_scene3_desc": "शिक्षण, भाषा, किताबहरू, कम्प्युटर र कार्यालयको काम अन्वेषण गर्नुहोस्। <em>lærer (शिक्षक), elev (विद्यार्थी), bog (किताब), computer (कम्प्युटर), papir (कागज), opgave (कार्य), spørgsmål (प्रश्न), svar (उत्तर), møde (बैठक)</em>, र <em>arbejde (काम)</em> जस्ता शब्दहरू सिक्नुहोस्।",
