    "top100_scene4_title": "🌲 प्रकृति र फुर्सदको समय",
    "top100_scene4_desc": "जङ्गल, समुद्र तट, मौसम, शरीर र फुर्सदका गतिविधिहरू अन्वेषण गर्नुहोस्। <em>skov (जङ्गल), strand (समुद्र तट), vejr (मौसम), fugl (चरा), blomst (फूल), hånd (हात), hoved (टाउको), fod (खुट्टा), musik (सङ्गीत), film (चलचित्र), spil (खेल)</em>, र <em>ferie (बिदा)</em> जस्ता शब्दहरू सिक्नुहोस्।",
