    "top100VerberDesc": "जीवन्त चित्रित दृश्यहरू र पर्यायवाची तथा विपरितार्थी शब्दका अभ्यासहरू मार्फत डेनिस भाषाका १०० सबैभन्दा बढी प्रयोग हुने क्रियाहरूमा निपुणता हासिल गर्नुहोस्।",
