    "top100_verber_hub_desc": "क्रियाहरू भाषाका इन्जिन हुन् जसले कार्यहरू, चालहरू र अवस्थाहरू व्यक्त गर्दछन्। प्रत्येकमा २० वटा क्रियाहरू भएका पाँचवटा जीवन्त दृश्यहरूमा १०० सबैभन्दा सामान्य क्रियाहरू अन्वेषण गर्नुहोस्।",
