    "top100_scene1_badge": "🏙️ ฉากที่ 1: ประมาณ 60–70% ของคำศัพท์",
    "top100_scene1_title": "🏙️ เมือง",
    "top100_scene1_desc": "สำรวจท้องถนน จัตุรัสเมือง โรงเรียน ร้านค้า และผู้คนในเมือง เรียนรู้คำศัพท์ที่พบบ่อย เช่น <em>mand (ผู้ชาย), kvinde (ผู้หญิง), bil (รถยนต์), vej (ถนน), skole (โรงเรียน), tid (เวลา), penge (เงิน), læge (แพทย์)</em> และ <em>tur (การเดินทาง)</em>",
