    "top100_scene2_title": "🍳 บ้านและห้องครัว",
    "top100_scene2_desc": "สำรวจมื้ออาหารของครอบครัว อาหาร เฟอร์นิเจอร์ และเสื้อผ้าที่บ้าน เรียนรู้คำศัพท์ เช่น <em>mor (แม่), far (พ่อ), barn (เด็ก), bord (โต๊ะ), stol (เก้าอี้), kop (ถ้วย), kaffe (กาแฟ), mad (อาหาร), seng (เตียง), hund (สุนัข)</em> และ <em>problem (ปัญหา)</em>",
    "top100_scene2_btn": "ไปที่ห้องครัว ➔",
    "top100_scene3_badge": "📚 ฉากที่ 3: ความรู้และภาษา",
    "top100_scene3_title": "🏫 ห้องเรียนและสำนักงาน",
    "top100_scene3_desc": "สำรวจการเรียนการสอน ภาษา หนังสือ คอมพิวเตอร์ และการทำงานในสำนักงาน เรียนรู้คำศัพท์ เช่น <em>lærer (ครู), elev (นักเรียน), bog (หนังสือ), computer (คอมพิวเตอร์), papir (กระดาษ), opgave (แบบฝึกหัด/งาน), spørgsmål (คำถาม), svar (คำตอบ), møde (การประชุม)</em> และ <em>arbejde (งาน)</em>",
    "top100_scene3_btn": "ไปที่ห้องเรียน ➔",
    "top100_scene4_title": "🌲 ธรรมชาติและเวลาว่าง",
    "top100_scene4_desc": "สำรวจป่า ชายหาด สภาพอากาศ ร่างกาย และกิจกรรมยามว่าง เรียนรู้คำศัพท์ เช่น <em>skov (ป่า), strand (ชายหาด), vejr (สภาพอากาศ), fugl (นก), blomst (ดอกไม้), hånd (มือ), hoved (ศีรษะ), fod (เท้า), musik (ดนตรี), film (ภาพยนตร์), spil (เกม)</em> และ <em>ferie (วันหยุด)</em>",
    "top100_scene4_btn": "ไปที่ธรรมชาติ ➔",
