    "top100_scene5_desc": "สำรวจสถานีรถไฟ ร้านขายของชำ ปฏิทิน และช่วงเวลาของวัน เรียนรู้คำศัพท์ เช่น <em>tog (รถไฟ), billet (ตั๋ว), butik (ร้านค้า), brød (ขนมปัง), mælk (นม), æble (แอปเปิ้ล), pris (ราคา), morgen (ตอนเช้า), aften (ตอนเย็น)</em> และ <em>år (ปี)</em>",
