    "top100_scene1_title": "🏙️ Thành phố",
    "top100_scene1_desc": "Khám phá đường phố, quảng trường, trường học, cửa hàng và cư dân thành phố. Học các từ có tần suất cao như <em>mand (đàn ông), kvinde (phụ nữ), bil (xe ô tô), vej (đường phố), skole (trường học), tid (thời gian), penge (tiền), læge (bác sĩ)</em> và <em>tur (chuyến đi)</em>.",
    "top100_scene1_btn": "Đến thành phố ➔",
    "top100_scene2_badge": "🍳 Cảnh 2: Nhà cửa & Gia đình",
    "top100_scene2_title": "🍳 Ngôi nhà và nhà bếp",
    "top100_scene2_desc": "Khám phá các bữa ăn gia đình, thực phẩm, đồ nội thất và quần áo tại nhà. Học các từ như <em>mor (mẹ), far (bố), barn (con/trẻ em), bord (bàn), stol (ghế), kop (tách/ly), kaffe (cà phê), mad (thức ăn), seng (giường), hund (chó)</em> và <em>problem (vấn đề)</em>.",
    "top100_scene2_btn": "Đến nhà bếp ➔",
    "top100_scene3_badge": "📚 Cảnh 3: Tri thức & Ngôn ngữ",
    "top100_scene3_title": "🏫 Phòng học và văn phòng",
    "top100_scene3_desc": "Khám phá việc giảng dạy, ngôn ngữ, sách vở, máy tính và công việc văn phòng. Học các từ như <em>lærer (giáo viên), elev (học sinh), bog (sách), computer (máy tính), papir (giấy), opgave (bài tập), spørgsmål (câu hỏi), svar (câu trả lời), møde (cuộc họp)</em> và <em>arbejde (công việc)</em>.",
    "top100_scene3_btn": "Đến phòng học ➔",
    "top100_scene4_title": "🌲 Thiên nhiên và thời gian rảnh rỗi",
    "top100_scene4_desc": "Khám phá rừng cây, bãi biển, thời tiết, cơ thể và các hoạt động giải trí. Học các từ như <em>skov (khu rừng), strand (bãi biển), vejr (thời tiết), fugl (chim), blomst (hoa), hånd (tay), hoved (đầu), fod (chân), musik (âm nhạc), film (phim), spil (trò chơi)</em> và <em>ferie (kỳ nghỉ)</em>.",
    "top100_scene4_btn": "Đến với thiên nhiên ➔",
    "top100_scene5_title": "🚆 Nhà ga, mua sắm và thời gian",
    "top100_scene5_desc": "Khám phá nhà ga xe lửa, cửa hàng tạp hóa, lịch và các thời điểm trong ngày. Học các từ như <em>tog (tàu hỏa), billet (vé), butik (cửa hàng), brød (bánh mì), mælk (sữa), æble (táo), pris (giá cả), morgen (buổi sáng), aften (buổi tối)</em> và <em>år (năm)</em>.",
    "top100_scene5_btn": "Đến nhà ga ➔",
