    "top100_scene1_title": "🏙️ المدينة",
    "top100_scene1_desc": "استكشف الشارع، وساحة المدينة، والمدرسة، والمتاجر، وسكان المدينة. تعلّم كلمات شائعة الاستخدام مثل <em>mand (رجل)، وkvinde (امرأة)، وbil (سيارة)، وvej (شارع)، وskole (مدرسة)، وtid (وقت)، وpenge (نقود)، وlæge (طبيب)</em>، و<em>tur (جولة)</em>.",
    "top100_scene1_btn": "الانتقال إلى المدينة ➔",
    "top100_scene2_badge": "🍳 المشهد 2: المنزل والعائلة",
    "top100_scene2_title": "🍳 المنزل والمطبخ",
    "top100_scene2_desc": "استكشف وجبات العائلة، والطعام، والأثاث، والملابس في المنزل. تعلّم كلمات مثل <em>mor (أم)، وfar (أب)، وbarn (طفل)، وbord (طاولة)، وstol (كرسي)، وkop (فنجان)، وkaffe (قهوة)، وmad (طعام)، وseng (سرير)، وhund (كلب)</em>، و<em>problem (مشكلة)</em>.",
    "top100_scene2_btn": "الانتقال إلى المطبخ ➔",
    "top100_scene3_badge": "📚 المشهد 3: المعرفة واللغة",
    "top100_scene3_title": "🏫 الفصل الدراسي والمكتب",
    "top100_scene3_desc": "استكشف التدريس، واللغة، والكتب، وأجهزة الكمبيوتر، والعمل المكتبي. تعلّم كلمات مثل <em>lærer (معلم)، وelev (طالب)، وbog (كتاب)، وcomputer (كمبيوتر)، وpapir (ورق)، وopgave (مهمة/واجب)، وspørgsmål (سؤال)، وsvar (إجابة)، وmøde (اجتماع)</em>، و<em>arbejde (عمل)</em>.",
    "top100_scene3_btn": "الانتقال إلى الفصل ➔",
    "top100_scene4_title": "🌲 الطبيعة وأوقات الفراغ",
    "top100_scene4_desc": "استكشف الغابة، والشاطئ، والطقس، والجسم، وأنشطة أوقات الفراغ. تعلّم كلمات مثل <em>skov (غابة)، وstrand (شاطئ)، وvejr (طقس)، وfugl (طائر)، وblomst (زهرة)، وhånd (يد)، وhoved (رأس)، وfod (قدم)، وmusik (موسيقى)، وfilm (فيلم)، وspil (لعبة)</em>، و<em>ferie (عطلة)</em>.",
